## 1️⃣ `setup_ultra_automation.bat`

Copy everything below into a file named **`setup_ultra_automation.bat`** and save it in a working folder (for example: `C:\Users\YourName\ChatGpt-Business\UltraAutomation\`).

```bat
@echo off
setlocal

set "ROOT=UltraAutomationTool"
echo Creating folder structure...
mkdir "%ROOT%"
mkdir "%ROOT%\automations"

REM =========================
REM excel_cleaner.py
REM =========================
> "%ROOT%\automations\excel_cleaner.py" (
echo import pandas as pd
echo import os
echo
echo def clean_excel(input_file, output_file):
echo ^    df = pd.read_excel(input_file)
echo ^    df = df.drop_duplicates()
echo ^    df = df.dropna(how="all")
echo ^    df.columns = [c.strip().lower().replace(" ", "_") for c in df.columns]
echo ^    df.to_excel(output_file, index=False)
echo ^    return output_file
)

REM =========================
REM pdf_text_extract.py
REM =========================
> "%ROOT%\automations\pdf_text_extract.py" (
echo import PyPDF2
echo
echo def extract_pdf_text(pdf_path, output_txt):
echo ^    reader = PyPDF2.PdfReader(pdf_path)
echo ^    text = ""
echo ^    for page in reader.pages:
echo ^        page_text = page.extract_text()
echo ^        if page_text:
echo ^            text += page_text + "\n"
echo ^    with open(output_txt, "w", encoding="utf-8") as f:
echo ^        f.write(text)
echo ^    return output_txt
)

REM =========================
REM csv_merger.py
REM =========================
> "%ROOT%\automations\csv_merger.py" (
echo import pandas as pd
echo import glob
echo import os
echo
echo def merge_csv(folder_path, output_file):
echo ^    pattern = os.path.join(folder_path, "*.csv")
echo ^    files = glob.glob(pattern)
echo ^    if not files:
echo ^        raise FileNotFoundError("No CSV files found in folder")
echo ^    df = pd.concat((pd.read_csv(f) for f in files), ignore_index=True)
echo ^    df.to_csv(output_file, index=False)
echo ^    return output_file
)

REM =========================
