> "%ROOT%\gui_main.py" (
echo import PySimpleGUI as sg
echo from automations.excel_cleaner import clean_excel
echo from automations.pdf_text_extract import extract_pdf_text
echo from automations.csv_merger import merge_csv
echo
echo sg.theme("DarkBlue3")
echo
echo layout = ^
[
echo ^    [sg.Text("ULTRA AUTOMATION TOOL", font=("Arial", 18))],
echo ^    [sg.Text("Select Task:"), sg.Combo(
echo ^        ["Clean Excel", "Extract PDF Text", "Merge CSV"],
echo ^        key="task",
echo ^        readonly=True
echo ^    )],
echo ^    [sg.Text("Input Path:"), sg.Input(key="in"), sg.FileBrowse()],
echo ^    [sg.Text("Output Path:"), sg.Input(key="out"), sg.FileSaveAs()],
echo ^    [sg.Button("Run"), sg.Button("Exit")],
echo ^    [sg.Output(size=(80, 15))]
echo ]
echo
echo window = sg.Window("Ultra Automation Tool", layout)
echo
echo while True:
echo ^    event, values = window.read()
echo ^    if event == sg.WIN_CLOSED or event == "Exit":
