echo ^            print("Please choose task, input, and output.")
echo ^            continue
echo
echo ^        try:
echo ^            if task == "Clean Excel":
echo ^                result = clean_excel(inp, out)
echo ^            elif task == "Extract PDF Text":
echo ^                result = extract_pdf_text(inp, out)
echo ^            elif task == "Merge CSV":
echo ^                result = merge_csv(inp, out)
echo ^            else:
echo ^                result = "Unknown task"
echo
echo ^            print("Task completed. Output:", result)
echo ^        except Exception as e:
echo ^            print("Error:", e)
echo
echo window.close()
)

